begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
('08000000-0000-4000-8000-000000000001','customer-owner@example.test',now()),('08000000-0000-4000-8000-000000000002','customer-admin@example.test',now()),('08000000-0000-4000-8000-000000000003','customer-barber@example.test',now()),('08000000-0000-4000-8000-000000000004','customer-other@example.test',now());
insert into public.businesses(id,slug,name) values('18000000-0000-4000-8000-000000000001','customer-alpha','Customer A'),('18000000-0000-4000-8000-000000000002','customer-beta','Customer B');
insert into public.business_members(id,business_id,user_id,role) values
('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000001','owner'),
('28000000-0000-4000-8000-000000000002','18000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000002','admin'),
('28000000-0000-4000-8000-000000000003','18000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000003','barber'),
('28000000-0000-4000-8000-000000000004','18000000-0000-4000-8000-000000000002','08000000-0000-4000-8000-000000000004','owner');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('public.customers'::regclass,'app.customer_requests'::regclass)),'customer tables force RLS');
select ok(not exists(select 1 from unnest(array['anon','authenticated','app_server','service_role']) r cross join unnest(array['public.customers','app.customer_requests']) t where has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'customer tables deny all application grants');
select ok(not exists(select 1 from unnest(array['anon','app_server','service_role']) r where has_function_privilege(r,'api.read_customer(uuid,uuid)','EXECUTE') or has_function_privilege(r,'api.write_customer(uuid,uuid,text,jsonb,uuid,integer)','EXECUTE')),'technical and anonymous roles have no customer capabilities');
select is(app.customer_phone('011 15 2345-6789')->>'phone_status','needs_review','national numbers not guessed');
select is(app.customer_phone('+54 9 11 2345-6789')->>'phone_e164','+5491123456789','international syntax normalized');
select throws_ok($$select app.customer_phone('++54')$$,'PT400','VALIDATION_ERROR','bad phone rejected');
select throws_ok($$select app.customer_payload('{"full_name":"Ana","email":"a..b@example.test"}')$$,'PT400','VALIDATION_ERROR','email subset matches TypeScript');
set local role authenticated;
set local "request.jwt.claim.sub"='08000000-0000-4000-8000-000000000003';
set local "request.jwt.claims"='{"aal":"aal1"}';
select throws_ok($$select api.list_customers_page('18000000-0000-4000-8000-000000000001')$$,'PT403','FORBIDDEN','barber cannot list customers');
select throws_ok($$select api.read_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001')$$,'PT403','FORBIDDEN','barber cannot probe nonexistent customer');
select throws_ok($$select api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','update','{}',gen_random_uuid(),null)$$,'PT403','FORBIDDEN','barber authorization before preconditions or validation');
set local "request.jwt.claim.sub"='08000000-0000-4000-8000-000000000001';
select throws_ok($$select api.list_customers_page('18000000-0000-4000-8000-000000000001')$$,'PT403','MFA_REQUIRED','owner requires aal2');
set local "request.jwt.claims"='{"aal":"aal2"}';
select is(api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','create','{"full_name":" Ana ","phone_raw":"+54 9 11 2345-6789","email":"shared@example.test","instagram_handle":"shared","private_notes":"Private fixture note"}','58000000-0000-4000-8000-000000000001',null)->>'version','1','create with metadata only');
select is(api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000002','create','{"full_name":"Ana","phone_raw":"+54 9 11 2345-6789","email":"shared@example.test","instagram_handle":"shared"}','58000000-0000-4000-8000-000000000002',null)->>'version','1','same tenant contacts and names may be shared');
select is(api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','create','{"full_name":"Ana","phone_raw":"+54 9 11 2345-6789","email":"shared@example.test","instagram_handle":"shared","private_notes":"Private fixture note"}','58000000-0000-4000-8000-000000000001',null)->>'version','1','normalized create replay is one effect');
select ok(not (api.list_customers_page('18000000-0000-4000-8000-000000000001')->'data'->0 ? 'private_notes'),'list excludes private notes');
select is(api.read_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001')->>'private_notes','Private fixture note','authorized detail exposes notes');
select throws_ok($$select api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','create','{"full_name":"Different"}','58000000-0000-4000-8000-000000000001',null)$$,'PT409','IDEMPOTENCY_KEY_REUSED','changed intent cannot replay');
select throws_ok($$select api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','update','{"full_name":"Changed"}',gen_random_uuid(),null)$$,'PT428','PRECONDITION_REQUIRED','missing version rejected');
select throws_ok($$select api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','update','{"full_name":"Changed"}',gen_random_uuid(),9)$$,'PT412','PRECONDITION_FAILED','stale version rejected');
select is(api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','archive','{}','58000000-0000-4000-8000-000000000003',1)->>'version','2','archive is logical and versioned');
select is(api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','restore','{}','58000000-0000-4000-8000-000000000004',2)->>'version','3','restore preserves identity');
set local "request.jwt.claim.sub"='08000000-0000-4000-8000-000000000004';
select throws_ok($$select api.read_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001')$$,'PT404','NOT_FOUND','foreign tenant denied');
reset role;
select is((select marketing_revision from public.customers where id='38000000-0000-4000-8000-000000000001'),2,'archive invalidates context; restore never revives epoch');
select is((select count(*) from auth.users where id::text like '08000000-%'),4::bigint,'customer writes create no accounts');
select ok(not exists(select 1 from app.customer_requests where result::text like '%Private fixture%') and not exists(select 1 from public.audit_logs where business_id='18000000-0000-4000-8000-000000000001' and after_data::text like '%Ana%'),'replay and audit omit PII');
update app.customer_requests set created_at=clock_timestamp()-interval '49 hours' where key='58000000-0000-4000-8000-000000000001';
select throws_ok('select app.purge_customer_requests(501)','PT400','VALIDATION_ERROR','bounded private purger');
select is(app.purge_customer_requests(500),1,'purge removes only expired replay');
set local role authenticated;
set local "request.jwt.claim.sub"='08000000-0000-4000-8000-000000000001';
select throws_ok($$select api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','create','{"full_name":"Ana"}','58000000-0000-4000-8000-000000000001',null)$$,'PT409','DUPLICATE_RESOURCE','expired create key cannot duplicate stable customer UUID');
select throws_ok($$select api.list_customers_page('18000000-0000-4000-8000-000000000001','current','name',null,'prefix',201)$$,'PT400','VALIDATION_ERROR','page max 200');
select throws_ok($$select api.list_customers_page('18000000-0000-4000-8000-000000000001','current','name',null,'prefix',50,'bad!')$$,'PT400','VALIDATION_ERROR','invalid cursor safe');
reset role;
insert into public.customers(id,business_id,full_name,private_notes,phone_status,created_at) select gen_random_uuid(),'18000000-0000-4000-8000-000000000001','Page fixture '||n,'Secret fixture note','missing','2026-01-01T00:00:00Z' from generate_series(1,451) n;
set local role authenticated;
select is(jsonb_array_length(api.list_customers_page('18000000-0000-4000-8000-000000000001')->'data'),50,'default page 50');
select is(jsonb_array_length(api.list_customers_page('18000000-0000-4000-8000-000000000001','current','name',null,'prefix',200)->'data'),200,'maximum page 200 no silent truncation');
select is(jsonb_array_length(api.list_customers_page('18000000-0000-4000-8000-000000000001','current','phone','+5491123456789','exact')->'data'),2,'search yields both shared-contact customers');
select throws_ok(format('select api.list_customers_page(%L,%L,%L,%L,%L,50,%L)','18000000-0000-4000-8000-000000000001','archived','name',null,'prefix',api.list_customers_page('18000000-0000-4000-8000-000000000001')->'page'->>'next_cursor'),'PT400','VALIDATION_ERROR','cursor bound to state filter');
select is(jsonb_array_length(api.list_customers_page('18000000-0000-4000-8000-000000000001','current','name','%_','prefix')->'data'),0,'wildcards are literal');
reset role;
select is((select count(*) from public.audit_logs where business_id='18000000-0000-4000-8000-000000000001'),4::bigint,'only successful commands audited, replay/purge preserve audit');
select throws_ok($$select app.customer_payload('[]')$$,'PT400','VALIDATION_ERROR','nonobject RPC payload classified safely');
select throws_ok($$select app.customer_payload('{"full_name":"Fixture","marketing_opt_in":true}')$$,'PT400','VALIDATION_ERROR','marketing input cannot be smuggled into profile');
create function pg_temp.fail_customer_audit() returns trigger language plpgsql as $$begin if new.action='customer.update' then raise exception 'FIXTURE_FAILURE'; end if;return new;end;$$;
create trigger fixture_customer_audit_failure before insert on public.audit_logs for each row execute function pg_temp.fail_customer_audit();
set local role authenticated;
select throws_ok($$select api.write_customer('18000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000001','update','{"full_name":"Rollback fixture"}','58000000-0000-4000-8000-000000000009',3)$$,'P0001','FIXTURE_FAILURE','audit failure rolls whole write back');
reset role;
select is((select full_name||':'||version from public.customers where id='38000000-0000-4000-8000-000000000001'),'Ana:3','failed write preserves previous profile and version');
select is((select count(*) from app.customer_requests where key='58000000-0000-4000-8000-000000000009'),0::bigint,'failed transaction leaves no replay effect');
update public.business_members set status='suspended' where id='28000000-0000-4000-8000-000000000002';
set local role authenticated;
set local "request.jwt.claim.sub"='08000000-0000-4000-8000-000000000002';
select throws_ok($$select api.list_customers_page('18000000-0000-4000-8000-000000000001')$$,'PT404','NOT_FOUND','each page reauthorizes current membership');
reset role;
select * from finish();
rollback;
